Action: run_sql({'query': '\nWITH viol AS (\n  SELECT i.slchd_establishment_key,\n         COUNT(*) AS total_violations,\n         SUM(CASE WHEN vc.critical THEN 1 ELSE 0 END) AS critical_violations\n  FROM violations v\n  JOIN inspections i ON v.inspection_id = i.inspection_id\n  JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n  GROUP BY i.slchd_establishment_key\n)\nSELECT\n  corr(e.avg_rating, COALESCE(v.total_violations,0)) AS corr_total_violations,\n  corr(e.avg_rating, COALESCE(v.critical_violations,0)) AS corr_critical_violations,\n  count(*) AS n\nFROM establishments e\nJOIN viol v ON e.slchd_establishment_key = v.slchd_establishment_key\nWHERE e.avg_rating IS NOT NULL;\n'})

